(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.3) * 18 + Math.cos(y * 0.013 - t * 0.22) * 12;
  const w1y = Math.cos(y * 0.019 - t * 0.27) * 18 + Math.sin(x * 0.016 + t * 0.37) * 12;
