  }
  const n = 8;
  const act = aS/n, inh = iS/n, wav = wS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.8) + Math.sin(sx*0.028-sy*0.038+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.5)*0.2 + Math.sin((sx-sy)*0.09-t*2)*0.2;
  const bg3 = Math.sin(sx*0.06+Math.sin(sy*0.04+t)*2+t*1.8)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3-t*1.5);
