  const diff = act - inh*0.65 + bg*0.25 + spiral*0.2 + lap*0.08 + wav*0.15;
  const reaction = Math.tanh(diff * 2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.09+t)*0.5 + Math.sin(sx*0.07-t*0.6)*Math.cos(sy*0.08+t*0.4)*0.4)*1.4)*0.25;
  const micro = Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.7 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,35,85],[14,65,120],[18,105,135],
    [30,150,145],[80,180,140],[160,195,110],
    [210,190,75],[225,160,60],[215,120,65],
    [190,80,70],[145,45,65],[90,25,60],[40,15,55],[6,12,52]
