  const bA = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.72 ? 1.12+Math.abs(reaction)*0.06 : 0.92+Math.abs(reaction)*0.08;
