  return [
    Math.min(255, ((rA*lum*edge + glow*60)|0))|0,
    Math.min(255, ((gA*lum*edge + glow*40)|0))|0,
    Math.min(255, ((bA*lum*edge + glow*80)|0))|0
  ];
}
